rocessSemantics5Riscv5Instr;branch_cond04K4ELinuxProcessSemantics5Riscv5Instr5aluop0:K4ELinuxProcessSemantics5Riscv5Instr5aluop05K4ELinuxProcessSemantics5Riscv5Instr5aluop06".
Import ListNotations.
Open Scope Z_scope.
Set Warnings "-notation-for-abbreviation".
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.

Ltac zto pc := repeat (lazymatch goal with |- evt _ _ (MS _ _ (Z_to_bv 64 pc) _ _ _ _) => fail | _ => zstep end).

Section CANSEC1. Context {rc : runConstT}.
Section DX2C.
  Variables (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32) (m0 : fmem).
  Variables (DST dcap SS DT mtl tl lo : Z) (src : list Z) (cells : list deltX2) (cbs : list byte).
  Notation SP := (bv_unsigned sp).
  Notation n := (zlen src).
  Hypothesis TOK : x2_table_ok cells tl.
  Hypothesis ECB : cbs = firstn (Z.to_nat (4 * 2^tl)) (x2_bytes' cells).     (* [comment removed for export] *)
  Hypothesis LCB : zlen cbs = 4 * 2^tl.
  Hypothesis MTL : 1 <= mtl <= 12.
  Hypothesis D0 : 0 <= DST.
  Hypothesis DP : 0 < dcap -> 8 <= DST.
  Hypothesis DC : 0 <= dcap < 2^32.
  Hypothesis DL : DST + dcap <= lo.
  Hypothesis S0 : 16 <= SS.
  Hypothesis SL : SS + n <= lo.
  Hypothesis NSM : n < 2^26.
  Hypothesis BYS : Forall (fun c => 0 <= c < 256) src.
  Hypothesis DT0 : 0 < DT.
  Hypothesis CBL : DT + 4 + 4 * 2^tl <= lo.
  Hypothesis DJ1 : DT + 4 + 4 * 2^tl <= DST \/ DST + dcap <= DT.
  Hypothesis DJ3 : DST + dcap <= SS \/ SS + n <= DST.
  Hypothesis LOS : lo <= SP - 4096.
  Hypothesis SP16 : SP mod 16 = 0.

  Notation DW := [(SP - 4096, SP); (DST, DST + dcap)].
  Notation POST := (huf_dec_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc DST dcap lo m0).
  Notation DINV := (RF_huf_dx1.DINV sp s0 s1 s2 s3 s4 s5 m0 DST dcap SS DT lo src cbs).
  Notation D2 l := (l ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc m0 DST dcap SS DT mtl tl lo src cells cbs
                      TOK ECB LCB MTL D0 DP DC DL S0 SL NSM BYS DT0 CBL DJ1 DJ3 LOS SP16) (only parsing).

  (* [comment removed for export] *)
  Ltac x2cell v :=
    lazymatch goal with |- context [Z_to_bv 64 (((bv_unsigned ?c ≪ ?b) mod 18446744073709551616) ≫ ?sh)] =>
      let EV := fresh "EV" in let VR := fresh "VR" in
      remember (((bv_unsigned c ≪ b) mod 18446744073709551616) ≫ sh) as v eqn:EV;
      assert (VR : 0 <= v < 2^tl)
        by (subst v; apply (D2 x2_idx_bound); [apply bv_unsigned_in_range| first [reflexivity | apply Z.mod_small; lia | lia]]);
      clear EV end.

  Ltac x2rd v c EC :=
    lazymatch goal with CE : bytes_at psegs ?mm (DT + 4) cbs, SQ : 0 <= x2_seq c < 65536 |- _ =>
      let RC0 := fresh "RC" in let RC2 := fresh "RC" in let RC3 := fresh "RC" in let RCB := fresh "RC" in
      destruct (x2_cell_rd psegs mm (DT + 4) cells (Z.to_nat (4 * 2^tl)) v c ltac:(rewrite <- ECB; exact CE)
                  ltac:(lia) ltac:(lia) ltac:(lia) EC SQ) as (RC0 & RC2 & RC3 & RCB) end.

  Ltac x2c v c EC :=
    lazymatch goal with TCK : forall i, 0 <= i < 2^tl -> _, VR : 0 <= v < 2^tl |- _ =>
      remember (nth (Z.to_nat v) cells x2_default) as c eqn:EC;
      let SQ := fresh "SQ" in let NB := fresh "NB" in let LN := fresh "LN" in
      destruct (TCK v VR) as (SQ & NB & LN); rewrite <- EC in SQ, NB, LN end.

  (* [comment removed for export] *)
  Ltac x2d OUT v c EC i padd :=
    zstep; zstep; x2cell v;
    zstep; zstep; rewrite (Z.shiftl_mul_pow2 v 2) by lia; change (2^2) with 4; replace (v * 4) with (4 * v) by ring;
    x2c v c EC; x2rd v c EC;
    zstep; (lazymatch padd with true => zstep | false => idtac end);
    zstep; unfold sx16;
    u8_sok OUT i; zstep; u8_store_same OUT i;
    u8_sok OUT (i + 1); zstep; u8_store_same OUT (i + 1);
    x2rd v c EC;
    zstep; zstep; rewrite ?(byte_lit (x2_nbBits c)), ?(byte_lit (x2_len c)) by lia;
    zstep.


  (* [comment removed for export] *)
  Lemma x2_dec4 : forall k bits mm (t0 t1 x8 x9 a1 a7 x18 x19 x20 x21 t3 t4 t5 t6 : word),
    DINV mm -> 0 <= k -> k + 8 <= dcap -> 0 <= bits <= 64 ->
    (forall k' bits' mm' (t1' x8' x9' : word), DINV mm' -> k + 4 <= k' <= k + 8 -> 0 <= bits' <= 112 ->
       evt psegs POST (MS (mkR ra (Z_to_bv 64 (SP + -48)) gp tp t0 t1' (Z_to_bv 64 (64 - tl)) x8' x9' (Z_to_bv 64 (DST + k')) a1
                              (Z_to_bv 64 SS) (Z_to_bv 64 (DT + 4)) (Z_to_bv 64 (tl + 256 * mtl)) (Z_to_bv 64 (DST + dcap))
                              (Z_to_bv 64 bits') a7 x18 x19 x20 x21 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                          F (Z_to_bv 64 0x14adc) fc None mm' (seg_rom psegs))) ->
    evt psegs POST (MS (mkR ra (Z_to_bv 64 (SP + -48)) gp tp t0 t1 (Z_to_bv 64 (64 - tl)) x8 x9 (Z_to_bv 64 (DST + k)) a1
                           (Z_to_bv 64 SS) (Z_to_bv 64 (DT + 4)) (Z_to_bv 64 (tl + 256 * mtl)) (Z_to_bv 64 (DST + dcap))
                           (Z_to_bv 64 bits) a7 x18 x19 x20 x21 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                       F (Z_to_bv 64 0x14a1c) fc None mm (seg_rom psegs)).
